.timeline-navigation button:hover { background: #fff8de; }
.timeline-navigation button.active { background: #FFDE09; color: #302500; }
.method-timeline .timeline-stages { display: grid; grid-template-columns: minmax(0,1fr); gap: 26px; position: relative; margin: 28px 0 36px; padding-left: 66px; }
.timeline-stages::before { content: ''; position: absolute; left: 22px; top: 20px; bottom: 20px; width: 3px; border-radius: 4px; background: linear-gradient(#FFDE09,#F7B325 45%,#AA1023); }
.method-timeline .timeline-stage { position: relative; display: grid; grid-template-columns: 180px minmax(0,1fr); gap: 26px; align-items: center; padding: 28px; border: 1px solid #e4e9ef; border-radius: 14px; background: #fff; box-shadow: 0 6px 24px #202a3505; scroll-margin-top: 160px; }
.method-timeline .timeline-stage:nth-child(even) { background: #fffcf3; }
.method-timeline .timeline-stage>.timeline-node { position: absolute; top: 28px; left: -65px; display: grid; place-items: center; width: 44px; height: 44px; border-radius: 50%; border: 4px solid #fff; box-shadow: 0 0 0 1px #eddfa8; background: #FFDE09; color: #302500; font-size: 14px; }
