.method-timeline .timeline-stage p+p { margin-top: 12px; }
.stage-entered { animation: stage-arrival .45s ease-out both; }
.stage-entered :deep(.illustration-symbol) { animation: illustration-arrival .7s ease-out; }
@keyframes stage-arrival { from { transform: translateY(14px); } to { transform: translateY(0); } }
@keyframes illustration-arrival { 0% { transform: translateY(7px) rotate(-5deg); } 60% { transform: translateY(-3px) rotate(2deg); } 100% { transform: translateY(0) rotate(0); } }
@media(max-width:1000px) { .method-timeline .timeline-stage { grid-template-columns: 130px minmax(0,1fr); gap: 18px; padding: 22px; } }
@media(max-width:760px) { .timeline-heading { gap: 10px; } .timeline-heading .section-label { font-size: 10px; } .timeline-counter { padding: 8px 12px; font-size: 12px; } .timeline-navigation { position: static; grid-template-columns: repeat(2,minmax(0,1fr)); padding: 8px; } .timeline-navigation button { font-size: 11px; padding: 8px; } .method-timeline .timeline-stages { padding-left: 38px; gap: 20px; } .timeline-stages::before { left: 12px; } .method-timeline .timeline-stage { grid-template-columns: minmax(0,1fr); gap: 12px; padding: 18px; scroll-margin-top: 18px; } .method-timeline .timeline-stage>.timeline-node { left: -42px; width: 32px; height: 32px; font-size: 11px; border-width: 3px; } .method-timeline .timeline-stage :deep(.method-illustration) { width: 130px; } .method-timeline .timeline-stage h3 { font-size: 17px; } .method-timeline .timeline-stage p { font-size: 13px; } }
@media(prefers-reduced-motion:reduce) { .stage-entered,.stage-entered :deep(.illustration-symbol) { animation: none; } }
</style>
